1	export const CHECKRIDE_COMPLETE_EVENT_TYPE_ID = 'checkride-complete';
2	export const CHECKRIDE_COMPLETION_EVENT_TITLE = 'Checkride Completion';
3	export const CHECKRIDE_COMPLETE_DURATION_MINUTES = 60;
4	
5	export type CheckrideScheduleEventTypeLike = {
6	  id?: string | null;
7	  name?: string | null;
8	  category?: string | null;
9	};
10	
11	function normalizeCheckrideEventTypeText(value: string | null | undefined) {
12	  return (value || '')
13	    .trim()
14	    .toLowerCase()
15	    .replace(/[()]/g, '')
16	    .replace(/[_\s]+/g, '-')
17	    .replace(/-+/g, '-');
18	}
19	
20	/** Matches canonical and custom Checkride Oral / Checkride Flight event types. */
21	export function isCheckrideSourceEventType(
22	  eventTypeId: string | null | undefined,
23	  eventType?: CheckrideScheduleEventTypeLike | null,
24	) {
25	  return [eventTypeId, eventType?.id, eventType?.name, eventType?.category]
26	    .map(normalizeCheckrideEventTypeText)
27	    .some(
28	      (value) => value === 'checkride-flight' || value === 'checkride-oral',
29	    );
30	}
31	
32	export function checkrideCompletionWindow(
33	  sourceEndAt: Date,
34	  durationMinutes = CHECKRIDE_COMPLETE_DURATION_MINUTES,
35	) {
36	  const normalizedDuration =
37	    Number.isFinite(durationMinutes) && durationMinutes > 0
38	      ? durationMinutes
39	      : CHECKRIDE_COMPLETE_DURATION_MINUTES;
40	  const startAt = new Date(sourceEndAt);
41	  const endAt = new Date(startAt.getTime() + normalizedDuration * 60_000);
42	  return { startAt, endAt };
43	}
44	
45	export function buildCheckrideCompletionEventInput({
46	  locationId,
47	  sourceEventId,
48	  sourceEndAt,
49	  studentIds,
50	  instructorId,
51	  checkrideHistoryId,
52	  completionEventTypeId = CHECKRIDE_COMPLETE_EVENT_TYPE_ID,
53	  durationMinutes = CHECKRIDE_COMPLETE_DURATION_MINUTES,
54	}: {
55	  locationId: string;
56	  sourceEventId: string;
57	  sourceEndAt: Date;
58	  studentIds: string[];
59	  instructorId: string;
60	  checkrideHistoryId: string;
61	  completionEventTypeId?: string;
62	  durationMinutes?: number;
63	}) {
64	  const { startAt, endAt } = checkrideCompletionWindow(
65	    sourceEndAt,
66	    durationMinutes,
67	  );
68	  return {
69	    locationId,
70	    title: CHECKRIDE_COMPLETION_EVENT_TITLE,
71	    type: completionEventTypeId,
72	    startAt,
73	    endAt,
74	    instructorId,
75	    instructorIds: [instructorId],
76	    studentId: studentIds[0],
77	    studentIds,
78	    status: 'scheduled',
79	    notes:
80	      'Record instructor checkride support time, official result, ACS outcomes, and upload the temporary certificate or FAA letter.',
81	    checkrideHistoryId,
82	    checkrideSourceEventId: sourceEventId,
83	  };
84	}
