1	import {
2	  MAX_DIRECT_DOCUMENT_UPLOAD_BYTES,
3	  MAX_DIRECT_DOCUMENT_UPLOAD_MB,
4	  getDocumentFileExtension,
5	  isAllowedDocumentUpload,
6	  normalizeDocumentUploadMimeType,
7	} from '@/lib/document-upload-policy';
8	
9	export const CHECKRIDE_OUTCOME_DOCUMENT_ACCEPT =
10	  '.pdf,.jpg,.jpeg,.png,.heic,.heif,application/pdf,image/jpeg,image/png,image/heic,image/heif';
11	
12	const ALLOWED_EXTENSIONS = new Set([
13	  'pdf',
14	  'jpg',
15	  'jpeg',
16	  'png',
17	  'heic',
18	  'heif',
19	]);
20	
21	export type CheckrideOutcomeDocumentFile = Pick<File, 'name' | 'size' | 'type'>;
22	
23	export function getCheckrideOutcomeDocumentMimeType(
24	  file: CheckrideOutcomeDocumentFile,
25	) {
26	  const normalized = normalizeDocumentUploadMimeType(file.name, file.type);
27	  if (normalized === 'image/jpg' || normalized === 'image/pjpeg') {
28	    return 'image/jpeg';
29	  }
30	  if (normalized === 'image/heic-sequence') return 'image/heic';
31	  if (normalized === 'image/heif-sequence') return 'image/heif';
32	  return normalized;
33	}
34	
35	export function validateCheckrideOutcomeDocument(
36	  file: CheckrideOutcomeDocumentFile,
37	): string | null {
38	  if (file.size <= 0) return 'This file is empty. Choose another document.';
39	  if (file.size > MAX_DIRECT_DOCUMENT_UPLOAD_BYTES) {
40	    return `This file is larger than ${MAX_DIRECT_DOCUMENT_UPLOAD_MB}MB. Choose a smaller document.`;
41	  }
42	
43	  const extension = getDocumentFileExtension(file.name);
44	  if (
45	    !ALLOWED_EXTENSIONS.has(extension) ||
46	    !isAllowedDocumentUpload(file.name, file.type)
47	  ) {
48	    return 'Use a PDF, JPG, PNG, HEIC, or HEIF document.';
49	  }
50	
51	  return null;
52	}
