1	export const CHECKRIDE_COMPLETE_CATEGORY = 'Checkride Complete';
2	
3	export type CheckrideCompletionBillingMode = 'none' | 'review' | 'auto';
4	
5	export type CheckrideCompletionEventTypeLike = {
6	  id?: string | null;
7	  name?: string | null;
8	  category?: string | null;
9	  defaultDuration?: number | null;
10	  unbillable?: boolean | null;
11	  autoBillStudent?: boolean | null;
12	  billLinkedCheckrideFee?: boolean | null;
13	  color?: string | null;
14	  checkedOutColor?: string | null;
15	  checkedInColor?: string | null;
16	  completedColor?: string | null;
17	};
18	
19	type CheckrideCompletionEventTypeIdentity = {
20	  id?: unknown;
21	  name?: unknown;
22	  category?: unknown;
23	};
24	
25	const CHECKRIDE_COMPLETION_FLOW_STEPS = {
26	  checkin: true,
27	  logLesson: false,
28	  logbook: false,
29	  invoice: false,
30	  signoff: false,
31	} as const;
32	
33	const CHECKRIDE_COMPLETION_STUDENT_FLOW_STEPS = {
34	  checkin: false,
35	  logLesson: false,
36	  logbook: false,
37	  invoice: false,
38	  signoff: false,
39	} as const;
40	
41	const CHECKRIDE_COMPLETION_LOGBOOK_REQUIREMENTS = {
42	  requiresRoute: false,
43	  requiresLandings: false,
44	  requiresHobbsTach: false,
45	  requiresApproaches: false,
46	  requiresNightTime: false,
47	  requiresCrossCountry: false,
48	  requiresPICTime: false,
49	  requiresSICTime: false,
50	  requiresDualReceived: false,
51	  requiresDualGiven: false,
52	  requiresSoloTime: false,
53	  requiresActualInstrument: false,
54	  requiresSimulatedInstrument: false,
55	  requiresRemarks: true,
56	} as const;
