58	function normalizeCheckrideCompletionText(value: string | null | undefined) {
59	  return (value || '')
60	    .trim()
61	    .toLowerCase()
62	    .replace(/[()]/g, '')
63	    .replace(/[_\s]+/g, '-');
64	}
65	
66	function normalizeCheckrideCompletionColor(
67	  value: string | null | undefined,
68	  fallback: string,
69	) {
70	  return typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value.trim())
71	    ? value.trim().toLowerCase()
72	    : fallback;
73	}
74	
75	export function isCheckrideCompleteCategory(
76	  category: string | null | undefined,
77	) {
78	  return normalizeCheckrideCompletionText(category) === 'checkride-complete';
79	}
80	
81	/** Matches the configured completion type as well as the legacy built-in id. */
82	export function isCheckrideCompletionEventType(
83	  eventType: CheckrideCompletionEventTypeIdentity | null | undefined,
84	) {
85	  return (
86	    normalizeCheckrideCompletionText(
87	      typeof eventType?.id === 'string' ? eventType.id : undefined,
88	    ) === 'checkride-complete' ||
89	    isCheckrideCompleteCategory(
90	      typeof eventType?.category === 'string' ? eventType.category : undefined,
91	    ) ||
92	    normalizeCheckrideCompletionText(
93	      typeof eventType?.name === 'string' ? eventType.name : undefined,
94	    ) === 'checkride-complete'
95	  );
96	}
97	
98	export function getCheckrideCompletionBillingMode(
99	  eventType: CheckrideCompletionEventTypeLike,
100	): CheckrideCompletionBillingMode {
101	  if (eventType.unbillable !== false) return 'none';
102	  return eventType.autoBillStudent === true ? 'auto' : 'review';
103	}
104	
105	export function applyCheckrideCompletionBillingMode<
106	  T extends CheckrideCompletionEventTypeLike,
107	>(eventType: T, mode: CheckrideCompletionBillingMode): T {
108	  return {
109	    ...eventType,
110	    unbillable: mode === 'none',
111	    autoBillStudent: mode === 'auto',
112	  };
113	}
114	
115	/**
116	 * Checkride completion has a deliberately small three-state color model.
117	 * All active scheduler statuses share the configured Started color.
118	 */
119	export function getCheckrideCompletionStatusColor(
120	  eventType: CheckrideCompletionEventTypeLike,
121	  status: string | null | undefined,
122	) {
123	  const normalizedStatus = (status || 'scheduled').trim().toLowerCase();
124	  if (normalizedStatus === 'completed') {
125	    return eventType.completedColor || '#6b7280';
126	  }
127	  if (
128	    normalizedStatus === 'checked-out' ||
129	    normalizedStatus === 'checked-in' ||
130	    normalizedStatus === 'in-progress'
131	  ) {
132	    return (
133	      eventType.checkedOutColor ||
134	      eventType.checkedInColor ||
135	      eventType.color ||
136	      '#0d9488'
137	    );
138	  }
139	  if (normalizedStatus === 'scheduled' || normalizedStatus === 'confirmed') {
140	    return eventType.color || '#059669';
141	  }
142	  return undefined;
143	}
144	
145	/**
146	 * Enforces the fixed resource and completion-flow requirements for this
147	 * category while preserving the location's billing and display choices.
148	 */
149	export function normalizeCheckrideCompletionEventType<
150	  T extends CheckrideCompletionEventTypeLike,
151	>(eventType: T): T {
152	  const billingMode = getCheckrideCompletionBillingMode(eventType);
153	  const requestedDuration = Number(eventType.defaultDuration);
154	  const defaultDuration =
155	    Number.isFinite(requestedDuration) && requestedDuration > 0
156	      ? Math.round(requestedDuration)
157	      : 60;
158	  const scheduledColor = normalizeCheckrideCompletionColor(
159	    eventType.color,
160	    '#059669',
161	  );
162	  const startedColor = normalizeCheckrideCompletionColor(
163	    eventType.checkedOutColor || eventType.checkedInColor,
164	    '#0d9488',
165	  );
166	  const completedColor = normalizeCheckrideCompletionColor(
167	    eventType.completedColor,
168	    '#6b7280',
169	  );
170	
171	  return applyCheckrideCompletionBillingMode(
172	    {
173	      ...eventType,
174	      category: CHECKRIDE_COMPLETE_CATEGORY,
175	      defaultDuration,
176	      color: scheduledColor,
177	      checkedOutColor: startedColor,
178	      checkedInColor: startedColor,
179	      completedColor,
180	      requiresAircraft: false,
181	      requiresSimulator: false,
182	      requiresRoom: false,
183	      requiresInstructor: true,
184	      requiresStudent: true,
185	      requiresHost: false,
186	      isMeetingFlow: false,
187	      isGroupEvent: false,
188	      groupBillingMode: 'per-student',
189	      flowSteps: { ...CHECKRIDE_COMPLETION_FLOW_STEPS },
190	      instructorFlowSteps: { ...CHECKRIDE_COMPLETION_FLOW_STEPS },
191	      studentFlowSteps: { ...CHECKRIDE_COMPLETION_STUDENT_FLOW_STEPS },
192	      requireStudentSignoff: false,
193	      allowStudentDispute: false,
194	      allowInstructorDispute: false,
195	      logbookRequirements: {
196	        ...CHECKRIDE_COMPLETION_LOGBOOK_REQUIREMENTS,
197	      },
198	      billLinkedCheckrideFee: eventType.billLinkedCheckrideFee !== false,
199	      cardTitleDisplay: 'event_type',
200	    },
201	    billingMode,
202	  );
203	}
