106	export function inferTrainingCertificateRating(
107	  value: string | null | undefined,
108	): Pick<
109	  DefaultTrainingCertificateRating,
110	  'code' | 'kind' | 'acsKey' | 'color'
111	> {
112	  const normalized = normalizeCertificateRatingText(value);
113	  if (!normalized) {
114	    return { code: '', kind: 'certificate', acsKey: null, color: '#0d9488' };
115	  }
116	  if (normalized.includes('private') || normalized === 'ppl') {
117	    return {
118	      code: 'PPL',
119	      kind: 'certificate',
120	      acsKey: 'PPL',
121	      color: '#0d9488',
122	    };
123	  }
124	  if (
125	    normalized.includes('instrument instructor') ||
126	    normalized.includes('cfii')
127	  ) {
128	    return { code: 'CFII', kind: 'rating', acsKey: 'CFII', color: '#047857' };
129	  }
130	  if (normalized.includes('instrument') || normalized === 'ir') {
131	    return { code: 'IR', kind: 'rating', acsKey: 'IFR', color: '#475569' };
132	  }
133	  if (normalized.includes('commercial') && normalized.includes('multi')) {
134	    return {
135	      code: 'MULTI',
136	      kind: 'rating',
137	      acsKey: 'COMM_MULTI',
138	      color: '#64748b',
139	    };
140	  }
141	  if (normalized.includes('commercial') || normalized === 'cpl') {
142	    return {
143	      code: 'CPL',
144	      kind: 'certificate',
145	      acsKey: 'COMM',
146	      color: '#0f766e',
147	    };
148	  }
149	  if (normalized.includes('multi engine instructor') || normalized === 'mei') {
150	    return {
151	      code: 'MEI',
152	      kind: 'certificate',
153	      acsKey: 'MEI',
154	      color: '#64748b',
155	    };
156	  }
157	  if (normalized.includes('multi')) {
158	    return {
159	      code: 'ME',
160	      kind: 'rating',
161	      acsKey: 'COMM_MULTI',
162	      color: '#64748b',
163	    };
164	  }
165	  if (normalized.includes('flight instructor') || normalized === 'cfi') {
166	    return {
167	      code: 'CFI',
168	      kind: 'certificate',
169	      acsKey: 'CFI',
170	      color: '#334155',
171	    };
172	  }
173	  if (normalized.includes('crew resource')) {
174	    return { code: 'CRM', kind: 'training', acsKey: null, color: '#7c3aed' };
175	  }
176	  if (normalized.includes('atp')) {
177	    return { code: 'ATP', kind: 'certificate', acsKey: null, color: '#1d4ed8' };
178	  }
179	  return {
180	    code: value
181	      ? value
182	          .replace(/[^a-zA-Z0-9]+/g, '')
183	          .slice(0, 8)
184	          .toUpperCase()
185	      : '',
186	    kind: 'certificate',
187	    acsKey: null,
188	    color: '#0d9488',
189	  };
190	}
