13	async function fireCheckoutRequestTrigger(
14	  flightSchoolId: string,
15	  locationId: string,
16	  stageCheckId: string,
17	  studentId: string,
18	  checkInstructorId: string | undefined,
19	  checkInstructorName: string | undefined,
20	  stageName: string,
21	  scheduledDate: Date,
22	): Promise<void> {
23	  try {
24	    const { triggerInstructorLeadWorkflowsForEvent } = await import(
25	      '@/lib/automations/triggerWorkflow'
26	    );
27	
28	    let studentName: string | null = null;
29	    let studentPhone: string | null = null;
30	
31	    const [student] = await db
32	      .select({ name: schema.users.name, phone: schema.users.phone })
33	      .from(schema.users)
34	      .where(eq(schema.users.id, studentId))
35	      .limit(1);
36	    if (student) {
37	      studentName = student.name ?? null;
38	      studentPhone = student.phone ?? null;
39	    }
40	
41	    let instructorName: string | null = checkInstructorName ?? null;
42	    let instructorPhone: string | null = null;
43	    if (checkInstructorId && isUuid(checkInstructorId)) {
44	      const rawId = checkInstructorId.startsWith('instructor-')
45	        ? checkInstructorId.slice('instructor-'.length)
46	        : checkInstructorId;
47	      const [instr] = await db
48	        .select({ name: schema.users.name, phone: schema.users.phone })
49	        .from(schema.users)
50	        .where(eq(schema.users.id, rawId))
51	        .limit(1);
52	      if (instr) {
53	        instructorName = instr.name ?? null;
54	        instructorPhone = instr.phone ?? null;
55	      }
56	    }
57	
58	    const [loc] = await db
59	      .select({ name: schema.locations.name })
60	      .from(schema.locations)
61	      .where(eq(schema.locations.id, locationId))
62	      .limit(1);
63	
64	    await triggerInstructorLeadWorkflowsForEvent(
65	      'instructor.checkout_request_submitted',
66	      {
67	        eventId: `checkout-request-${stageCheckId}`,
68	        flightSchoolId,
69	        locationId,
70	        locationName: loc?.name ?? null,
71	        studentId,
72	        studentName,
73	        studentPhone,
74	        instructorId: checkInstructorId ?? null,
75	        instructorName,
76	        instructorPhone,
77	        stageName,
78	        scheduledDate: scheduledDate.toISOString().substring(0, 10),
79	      },
80	      flightSchoolId,
81	      locationId,
82	    );
83	  } catch (err) {
84	    console.error(
85	      '[StageChecks] Error firing checkout_request_submitted trigger:',
86	      err,
87	    );
88	  }
89	}
