91	export const stageChecks = new Hono<{
92	  Variables: { authUser?: AuthUser };
93	}>();
94	
95	// ═══════════════════════════════════════════════════════════════════════════
96	// Tenant scoping
97	// ═══════════════════════════════════════════════════════════════════════════
98	//
99	// Every stage-check row is owned by exactly one flight school (flightSchoolId,
100	// NOT NULL on all four tables). requireAuth() only proves the caller is signed
101	// in — it does NOT bind them to a school. These helpers derive the caller's org
102	// from their session (never from request input) so a school-A user cannot read
103	// or write school-B rows by passing a different flightSchoolId or a foreign row
104	// id. Super-admins are cross-tenant by design (mirrors the assertFlightSchoolAccess
105	// pattern in routes-accounting.ts) and resolve to orgId=null, i.e. "no tenant
106	// constraint". The resolution fails closed: an unauthenticated caller or an
107	// unresolvable org yields 401/403, never a widened scope.
108	
109	type StageCheckScope =
110	  | { ok: true; orgId: string | null }
111	  | { ok: false; status: 401 | 403; error: string };
112	
113	/**
114	 * Resolves the caller's tenant scope. `orgId` is the session-derived flight
115	 * school every read/write MUST be constrained to; `null` means the caller is a
116	 * super-admin (cross-tenant by design — no constraint applied). Used directly by
117	 * row-by-id handlers, which add `flightSchoolId = orgId` to their WHERE clause
118	 * when `orgId` is non-null.
119	 */
120	async function resolveStageCheckScope(
121	  authUser: AuthUser | undefined,
122	  c: Context,
123	): Promise<StageCheckScope> {
124	  if (!authUser) return { ok: false, status: 401, error: 'Unauthorized' };
125	  if (authUser.role === 'super_admin') return { ok: true, orgId: null };
126	  const orgId = await resolveOrgIdFromSession(authUser, c);
127	  if (!orgId) {
128	    return { ok: false, status: 403, error: 'Could not resolve organization' };
129	  }
130	  return { ok: true, orgId };
131	}
132	
133	/**
134	 * For handlers that receive a `flightSchoolId` in the request (query or body):
135	 * asserts the caller may act on it and returns the effective flightSchoolId to
136	 * use for the operation. Non-super-admins are pinned to their session org — a
137	 * value that doesn't match is a tenant-boundary violation (403). Super-admins
138	 * pass the requested id through unchanged.
139	 */
140	async function assertStageCheckSchool(
141	  authUser: AuthUser | undefined,
142	  c: Context,
143	  requestedSchoolId: string,
144	): Promise<
145	  | { ok: true; flightSchoolId: string }
146	  | { ok: false; status: 401 | 403; error: string }
147	> {
148	  const scope = await resolveStageCheckScope(authUser, c);
149	  if (!scope.ok) return scope;
150	  if (scope.orgId && scope.orgId !== requestedSchoolId) {
151	    return {
152	      ok: false,
153	      status: 403,
154	      error: 'Forbidden: cross-school access denied',
155	    };
156	  }
157	  return { ok: true, flightSchoolId: scope.orgId ?? requestedSchoolId };
158	}
