160	/**
161	 * Tenant isolation must cover client-supplied referenced row IDs, not just the
162	 * top-level flightSchoolId. A stage-check row's `studentId` / `scheduleId` must
163	 * belong to the SAME school the row is being created in — otherwise a caller
164	 * who passes their own flightSchoolId could still attach a result to another
165	 * school's schedule or student. These return false when the referenced row does
166	 * not exist in `orgId`, so the handler can reject (404) before inserting.
167	 */
168	async function studentBelongsToOrg(
169	  studentId: string,
170	  orgId: string,
171	): Promise<boolean> {
172	  const [row] = await db
173	    .select({ id: schema.users.id })
174	    .from(schema.users)
175	    .where(
176	      and(
177	        eq(schema.users.id, studentId),
178	        eq(schema.users.flightSchoolId, orgId),
179	      ),
180	    )
181	    .limit(1);
182	  return !!row;
183	}
