791	
792	    const areaResults = await db
793	      .select()
794	      .from(schema.stageCheckAreaResults)
795	      .where(eq(schema.stageCheckAreaResults.stageCheckResultId, result.id));
796	
797	    // Fire stage check passed/failed workflow triggers
798	    if (body.overallResult === 'passed' || body.overallResult === 'failed') {
799	      void fireStageCheckTrigger(result, areaResults, flightSchoolId);
800	    }
801	
802	    return c.json({ result, areaResults }, 201);
803	  } catch (err: unknown) {
804	    const structured = formatErrorForUser(err, {
805	      feature: 'STGC',
806	      actor: (c.get('authUser') as AuthUser | undefined)?.id,
807	    });
808	    return c.json(
809	      {
810	        error: structured.message,
811	        reference_id: structured.reference_id,
812	        retry_safe: structured.retry_safe,
813	      },
814	      500,
815	    );
816	  }
817	});
