819	/** Fire training.stage_check_passed or training.stage_check_failed trigger. Non-blocking. */
820	async function fireStageCheckTrigger(
821	  result: schema.StageCheckResult,
822	  areaResults: schema.StageCheckAreaResult[],
823	  flightSchoolId: string,
824	): Promise<void> {
825	  try {
826	    const { triggerWorkflowsForEvent } = await import(
827	      '@/lib/automations/triggerWorkflow'
828	    );
829	
830	    // Resolve student info
831	    const [student] = await db
832	      .select({
833	        name: schema.users.name,
834	        phone: schema.users.phone,
835	        locationId: schema.users.locationId,
836	      })
837	      .from(schema.users)
838	      .where(eq(schema.users.id, result.studentId))
839	      .limit(1);
840	    if (!student) return;
841	
842	    // Build areas of concern string for failed checks
843	    const failedAreas = areaResults
844	      .filter((ar) => ar.result === 'fail')
845	      .map((ar) => ar.acsAreaName)
846	      .join(', ');
847	
848	    // Resolve location name
849	    let locationName: string | null = null;
850	    const locationId = result.locationId ?? student.locationId ?? '';
851	    if (locationId) {
852	      const [loc] = await db
853	        .select({ name: schema.locations.name })
854	        .from(schema.locations)
855	        .where(eq(schema.locations.id, locationId))
856	        .limit(1);
857	      if (loc) locationName = loc.name;
858	    }
859	
860	    const trigger =
861	      result.overallResult === 'passed'
862	        ? 'training.stage_check_passed'
863	        : 'training.stage_check_failed';
864	
865	    await triggerWorkflowsForEvent(
866	      trigger,
867	      {
868	        eventId: `stage_check:${result.id}`,
869	        locationId,
870	        flightSchoolId,
871	        studentId: result.studentId,
872	        studentName: student.name,
873	        studentPhone: student.phone ?? null,
874	        instructorId: result.checkInstructorId ?? null,
875	        instructorName: result.checkInstructorName ?? null,
876	        locationName,
877	        stageName: result.stageName ?? null,
878	        stageCheckResult: result.overallResult,
879	        areasOfConcern: failedAreas || null,
880	      },
881	      flightSchoolId,
882	      locationId,
883	    );
884	  } catch (err) {
885	    console.error('[StageChecks] Error firing stage check trigger:', err);
886	  }
887	}
