893	/**
894	 * GET /stage-checks/eligible-instructors?flightSchoolId=&studentId=&stageId=&locationId=
895	 *
896	 * Returns instructors who are eligible to conduct a stage check for this student/stage.
897	 * Eligibility rules (FAR 141 requirement):
898	 *   1. Must have role = 'instructor'
899	 *   2. Must be Active status
900	 *   3. Must have instructorMetadata.instructorRole in: Stage Check Instructor, Chief Pilot, Chief Instructor, Assistant Chief Instructor, Lead/Check Airman
901	 *   4. Must NOT have instructed this student in this stage (excluded as training instructor)
902	 */
903	stageChecks.get(
904	  '/stage-checks/eligible-instructors',
905	  requireAuth(),
906	  async (c) => {
907	    try {
908	      const requestedSchoolId = c.req.query('flightSchoolId') ?? '';
909	      const studentId = c.req.query('studentId') ?? '';
910	      const stageId = c.req.query('stageId') ?? '';
911	
912	      if (!isUuid(requestedSchoolId)) {
913	        return c.json({ error: 'Invalid flightSchoolId' }, 400);
914	      }
915	
916	      const scoped = await assertStageCheckSchool(
917	        c.get('authUser'),
918	        c,
919	        requestedSchoolId,
920	      );
921	      if (!scoped.ok) return c.json({ error: scoped.error }, scoped.status);
922	      const flightSchoolId = scoped.flightSchoolId;
923	
924	      // Fetch all active instructors for this school
925	      const instructors = await db
926	        .select()
927	        .from(schema.users)
928	        .where(
929	          and(
930	            eq(schema.users.flightSchoolId, flightSchoolId),
931	            eq(schema.users.role, 'instructor'),
932	            eq(schema.users.status, 'Active'),
933	          ),
934	        );
935	
936	      // Qualifying check instructor roles (must match values stored in instructorMetadata.instructorRole)
937	      const QUALIFYING_ROLES = [
938	        'Stage Check Instructor',
939	        'Chief Pilot',
940	        'Chief Instructor',
941	        'Assistant Chief Instructor',
942	        'Lead/Check Airman',
943	      ];
944	
945	      // Filter to only qualifying roles
946	      const qualified = instructors.filter((inst) => {
947	        const meta = inst.instructorMetadata as
948	          | Record<string, unknown>
949	          | null
950	          | undefined;
951	        const role = meta?.instructorRole as string | undefined;
952	        if (!role) return false;
953	        return QUALIFYING_ROLES.some(
954	          (qr) => role.toLowerCase() === qr.toLowerCase(),
955	        );
956	      });
957	
958	      // Find the student's primary instructor for this stage from schedule events.
959	      // Per FAR 141: only the instructor who provided training for THIS specific stage
960	      // is excluded from conducting the stage check — not instructors from other stages.
961	      let excludedInstructorIds = new Set<string>();
962	      if (isUuid(studentId) && stageId) {
963	        // Build the events query — scope to this stage's modules when stageId is a DB UUID.
964	        // stageId is a UUID when it comes from curriculumStages; scope exclusion to modules
965	        // in that stage. If stageId is not a UUID (e.g. a text slug from a JSON curriculum),
966	        // fall back to excluding all instructors who trained this student (conservative).
967	        let eventInstructorIds: string[] = [];
968	        if (isUuid(stageId)) {
969	          // Look up modules belonging to this curriculum stage
970	          const stageModules = await db
971	            .select({ id: schema.curriculumModules.id })
972	            .from(schema.curriculumModules)
973	            .where(eq(schema.curriculumModules.stageId, stageId));
974	
975	          const moduleIds = stageModules.map((m) => m.id.toString());
976	
977	          if (moduleIds.length > 0) {
978	            // Find schedule events where this student was trained on modules in this stage
979	            const events = await db
980	              .select({ instructorId: schema.scheduleEvents.instructorId })
981	              .from(schema.scheduleEvents)
982	              .where(
983	                and(
984	                  eq(schema.scheduleEvents.flightSchoolId, flightSchoolId),
985	                  eq(schema.scheduleEvents.studentId, studentId),
986	                  inArray(schema.scheduleEvents.trainingModuleId, moduleIds),
987	                ),
988	              );
989	            eventInstructorIds = events
990	              .map((e) => e.instructorId)
991	              .filter(Boolean) as string[];
992	          }
993	          // If the stage has no curriculum modules yet, no event-based exclusions apply.
994	        } else {
995	          // Non-UUID stageId (e.g. a text slug): conservatively exclude all instructors
996	          // who have trained this student in any event.
997	          const events = await db
998	            .select({ instructorId: schema.scheduleEvents.instructorId })
999	            .from(schema.scheduleEvents)
1000	            .where(
1001	              and(
1002	                eq(schema.scheduleEvents.flightSchoolId, flightSchoolId),
1003	                eq(schema.scheduleEvents.studentId, studentId),
1004	              ),
1005	            );
1006	          eventInstructorIds = events
1007	            .map((e) => e.instructorId)
1008	            .filter(Boolean) as string[];
1009	        }
1010	
1011	        // Also exclude the primary class instructor (always applies regardless of stage)
1012	        const enrollments = await db
1013	          .select({
1014	            instructorId: schema.classes.instructorId,
1015	          })
1016	          .from(schema.classEnrollments)
1017	          .innerJoin(
1018	            schema.classes,
1019	            eq(schema.classEnrollments.classId, schema.classes.id),
1020	          )
1021	          .where(
1022	            and(
1023	              eq(schema.classEnrollments.flightSchoolId, flightSchoolId),
1024	              eq(schema.classEnrollments.studentId, studentId),
1025	            ),
1026	          );
1027	
1028	        excludedInstructorIds = new Set([
1029	          ...eventInstructorIds,
1030	          ...(enrollments
1031	            .map((e) => e.instructorId)
1032	            .filter(Boolean) as string[]),
1033	        ]);
1034	      }
1035	
1036	      const eligible = qualified.map((inst) => ({
1037	        id: inst.id,
1038	        name: inst.name,
1039	        email: inst.email,
1040	        certificateNumber: inst.certificateNumber,
1041	        role:
1042	          (
1043	            inst.instructorMetadata as
1044	              | Record<string, unknown>
1045	              | null
1046	              | undefined
1047	          )?.instructorRole ?? 'Instructor',
1048	        excluded: excludedInstructorIds.has(inst.id),
1049	        exclusionReason: excludedInstructorIds.has(inst.id)
1050	          ? 'Provided training for this stage (FAR 141 requirement)'
1051	          : undefined,
1052	      }));
1053	
1054	      return c.json({ instructors: eligible });
1055	    } catch (err: unknown) {
1056	      const structured = formatErrorForUser(err, {
1057	        feature: 'STGC',
1058	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
1059	      });
1060	      return c.json(
1061	        {
1062	          error: structured.message,
1063	          reference_id: structured.reference_id,
1064	          retry_safe: structured.retry_safe,
1065	        },
1066	        500,
1067	      );
1068	    }
1069	  },
1070	);
