1073	// Stages for a Student (dynamic — resolved from enrolled curriculum)
1074	// ═══════════════════════════════════════════════════════════════════════════
1075	
1076	/**
1077	 * GET /stage-checks/stages?flightSchoolId=&studentId=
1078	 *
1079	 * Resolves the student's enrolled curriculum and returns all stages from that
1080	 * curriculum with per-stage module counts and student completion data.
1081	 *
1082	 * Enrollment resolution paths (mirrors routes-chat.ts curriculum resolver):
1083	 *   Path 1  (legacy):   classEnrollments → classes → trainingCourses.curriculumId
1084	 *   Path 1b (versioned): classEnrollments → classes → trainingCourses.curriculumVersionId → curriculumVersions.curriculumId
1085	 *   Path 2  (legacy):   users.assignedCourseId → trainingCourses.curriculumId
1086	 *   Path 2b (versioned): users.assignedCourseId → trainingCourses.curriculumVersionId → curriculumVersions.curriculumId
1087	 *
1088	 * Returns:
1089	 *   stages: Array<{
1090	 *     id: string;           // stage check module ID from curricula.stages JSONB
1091	 *     name: string;         // stage check module name (e.g. "Stage Check 1")
1092	 *     sortOrder: number;    // sort position of the parent stage
1093	 *     totalLessons: number; // lesson module count for the stage (excludes stage check modules)
1094	 *     completedLessons: number; // completed lesson events for the stage's lesson modules
1095	 *     eligible: boolean;    // true if >= 80% of stage lesson modules are completed
1096	 *   }>
1097	 *   curriculumId: string | null
1098	 *   curriculumTitle: string | null
1099	 */
1100	stageChecks.get('/stage-checks/stages', requireAuth(), async (c) => {
1101	  try {
1102	    const requestedSchoolId = c.req.query('flightSchoolId') ?? '';
1103	    const studentId = c.req.query('studentId') ?? '';
1104	
1105	    if (!isUuid(requestedSchoolId)) {
1106	      return c.json({ error: 'Invalid flightSchoolId' }, 400);
1107	    }
1108	    if (!isUuid(studentId)) {
1109	      return c.json({ error: 'Invalid studentId' }, 400);
1110	    }
1111	
1112	    const scoped = await assertStageCheckSchool(
1113	      c.get('authUser'),
1114	      c,
1115	      requestedSchoolId,
1116	    );
1117	    if (!scoped.ok) return c.json({ error: scoped.error }, scoped.status);
1118	    const flightSchoolId = scoped.flightSchoolId;
1119	
1120	    // ── Step 1: Resolve enrolled curriculum ID ──────────────────────────────
1121	    const curriculumIdSet = new Set<string>();
1122	
1123	    // Path 1 (legacy): classEnrollments → classes → trainingCourses.curriculumId
1124	    const enrollmentRows = await db
1125	      .select({ curriculumId: schema.trainingCourses.curriculumId })
1126	      .from(schema.classEnrollments)
1127	      .innerJoin(
1128	        schema.classes,
1129	        eq(schema.classEnrollments.classId, schema.classes.id),
1130	      )
1131	      .innerJoin(
1132	        schema.trainingCourses,
1133	        and(
1134	          eq(schema.trainingCourses.id, schema.classes.courseId),
1135	          isNotNull(schema.trainingCourses.curriculumId),
1136	        ),
1137	      )
1138	      .where(
1139	        and(
1140	          eq(schema.classEnrollments.flightSchoolId, flightSchoolId),
1141	          eq(schema.classEnrollments.studentId, studentId),
1142	        ),
1143	      );
1144	    for (const row of enrollmentRows) {
1145	      if (row.curriculumId) curriculumIdSet.add(row.curriculumId);
1146	    }
1147	
1148	    // Path 1b (versioned): classEnrollments → classes →
1149	    //   trainingCourses.curriculumVersionId → curriculumVersions.curriculumId
1150	    const enrollmentVersionRows = await db
1151	      .select({ curriculumId: schema.curriculumVersions.curriculumId })
1152	      .from(schema.classEnrollments)
1153	      .innerJoin(
1154	        schema.classes,
1155	        eq(schema.classEnrollments.classId, schema.classes.id),
1156	      )
1157	      .innerJoin(
1158	        schema.trainingCourses,
1159	        and(
1160	          eq(schema.trainingCourses.id, schema.classes.courseId),
1161	          isNotNull(schema.trainingCourses.curriculumVersionId),
1162	        ),
1163	      )
1164	      .innerJoin(
1165	        schema.curriculumVersions,
1166	        eq(
1167	          schema.curriculumVersions.id,
1168	          schema.trainingCourses.curriculumVersionId,
1169	        ),
1170	      )
1171	      .where(
1172	        and(
1173	          eq(schema.classEnrollments.flightSchoolId, flightSchoolId),
1174	          eq(schema.classEnrollments.studentId, studentId),
1175	        ),
1176	      );
1177	    for (const row of enrollmentVersionRows) {
1178	      if (row.curriculumId) curriculumIdSet.add(row.curriculumId);
1179	    }
1180	
1181	    // Path 2 (legacy): users.assignedCourseId → trainingCourses.curriculumId
1182	    const directRows = await db
1183	      .select({ curriculumId: schema.trainingCourses.curriculumId })
1184	      .from(schema.users)
1185	      .innerJoin(
1186	        schema.trainingCourses,
1187	        and(
1188	          eq(schema.trainingCourses.id, schema.users.assignedCourseId),
1189	          isNotNull(schema.trainingCourses.curriculumId),
1190	        ),
1191	      )
1192	      .where(eq(schema.users.id, studentId));
1193	    for (const row of directRows) {
1194	      if (row.curriculumId) curriculumIdSet.add(row.curriculumId);
1195	    }
1196	
1197	    // Path 2b (versioned): users.assignedCourseId →
1198	    //   trainingCourses.curriculumVersionId → curriculumVersions.curriculumId
1199	    const directVersionRows = await db
1200	      .select({ curriculumId: schema.curriculumVersions.curriculumId })
1201	      .from(schema.users)
1202	      .innerJoin(
1203	        schema.trainingCourses,
1204	        and(
1205	          eq(schema.trainingCourses.id, schema.users.assignedCourseId),
1206	          isNotNull(schema.trainingCourses.curriculumVersionId),
1207	        ),
1208	      )
1209	      .innerJoin(
1210	        schema.curriculumVersions,
1211	        eq(
1212	          schema.curriculumVersions.id,
1213	          schema.trainingCourses.curriculumVersionId,
1214	        ),
1215	      )
1216	      .where(eq(schema.users.id, studentId));
1217	    for (const row of directVersionRows) {
1218	      if (row.curriculumId) curriculumIdSet.add(row.curriculumId);
1219	    }
1220	
1221	    if (curriculumIdSet.size === 0) {
1222	      // No enrolled curriculum found — return empty stages list
1223	      return c.json({ stages: [], curriculumId: null, curriculumTitle: null });
1224	    }
1225	
1226	    // Use the first resolved curriculum (prefer class enrollment over direct course)
1227	    const resolvedCurriculumId = [...curriculumIdSet][0];
1228	
1229	    // ── Step 2: Fetch curriculum with stages JSONB ───────────────────────────
1230	    // Curriculum stages are stored in the curricula.stages JSONB column, not in
1231	    // the curriculumStages relational table. Read from the source of truth.
1232	    const [curriculumRow] = await db
1233	      .select({
1234	        id: schema.curricula.id,
1235	        title: schema.curricula.title,
1236	        stages: schema.curricula.stages,
1237	      })
1238	      .from(schema.curricula)
1239	      .where(
1240	        and(
1241	          eq(schema.curricula.id, resolvedCurriculumId),
1242	          eq(schema.curricula.flightSchoolId, flightSchoolId),
1243	        ),
1244	      )
1245	      .limit(1);
1246	
1247	    if (!curriculumRow) {
1248	      return c.json({
1249	        stages: [],
1250	        curriculumId: resolvedCurriculumId,
1251	        curriculumTitle: null,
1252	      });
1253	    }
1254	
1255	    // ── Step 3: Parse JSONB stages and collect stage check modules ───────────
1256	    // Each stage in the JSONB has { id, name|title, modules|lessons: [...] }.
1257	    // Stage check modules are identified by moduleType/type === 'stage-check'
1258	    // (the canonical kebab-case used by the curriculum editor) or by the
1259	    // display label eventType === 'Stage Check'. The legacy snake_case
1260	    // 'stage_check' value is also accepted in case any older curricula
1261	    // pre-date the kebab-case migration. One entry is returned per stage
1262	    // check module so the drawer shows exactly the stage checks available
1263	    // in this curriculum.
1264	    type JsonbMod = {
1265	      id?: string;
1266	      name?: string;
1267	      title?: string;
1268	      type?: string;
1269	      moduleType?: string;
1270	      eventType?: string;
1271	    };
1272	    type JsonbStage = {
1273	      id?: string;
1274	      name?: string;
1275	      title?: string;
1276	      modules?: JsonbMod[];
1277	      lessons?: JsonbMod[];
1278	      sortOrder?: number;
1279	    };
1280	
1281	    const jsonbStages = ((curriculumRow.stages as JsonbStage[]) ?? []).filter(
1282	      (s): s is JsonbStage & { id: string } => typeof s?.id === 'string',
1283	    );
1284	
1285	    const STAGE_CHECK_TYPES = new Set([
1286	      'stage-check',
1287	      'stage_check',
1288	      'Stage Check',
1289	    ]);
1290	    const FINAL_CHECK_TYPES = new Set([
1291	      'final-check',
1292	      'final_check',
1293	      'Final Check',
1294	      'Practical Test',
1295	    ]);
1296	
1297	    const isStageCheck = (m: JsonbMod) =>
1298	      (m.moduleType !== undefined && STAGE_CHECK_TYPES.has(m.moduleType)) ||
1299	      (m.type !== undefined && STAGE_CHECK_TYPES.has(m.type)) ||
1300	      (m.eventType !== undefined && STAGE_CHECK_TYPES.has(m.eventType));
1301	
1302	    const isFinalCheck = (m: JsonbMod) =>
1303	      (m.moduleType !== undefined && FINAL_CHECK_TYPES.has(m.moduleType)) ||
1304	      (m.type !== undefined && FINAL_CHECK_TYPES.has(m.type)) ||
1305	      (m.eventType !== undefined && FINAL_CHECK_TYPES.has(m.eventType));
1306	
1307	    const isLesson = (m: JsonbMod) => !isStageCheck(m) && !isFinalCheck(m);
1308	
1309	    // Build entries: one per stage check module found across all stages.
1310	    // Each entry tracks the lesson (non-stage-check) module IDs in the same
1311	    // stage so we can compute completion and eligibility.
1312	    const stageCheckEntries: Array<{
1313	      id: string;
1314	      name: string;
1315	      stageName: string;
1316	      sortOrder: number;
1317	      lessonModuleIds: string[];
1318	    }> = [];
1319	
1320	    for (let idx = 0; idx < jsonbStages.length; idx++) {
1321	      const stage = jsonbStages[idx];
1322	      const mods: JsonbMod[] = stage.modules?.length
1323	        ? stage.modules
1324	        : (stage.lessons ?? []);
1325	
1326	      const stageCheckMods = mods.filter(
1327	        (m): m is JsonbMod & { id: string } =>
1328	          isStageCheck(m) && typeof m.id === 'string',
1329	      );
1330	      const lessonModuleIds = mods
1331	        .filter(
1332	          (m): m is JsonbMod & { id: string } =>
1333	            isLesson(m) && typeof m.id === 'string',
1334	        )
1335	        .map((m) => m.id);
1336	
1337	      const stageName = stage.name ?? stage.title ?? `Stage ${idx + 1}`;
1338	
1339	      for (const scMod of stageCheckMods) {
1340	        stageCheckEntries.push({
1341	          id: scMod.id,
1342	          name: scMod.name ?? scMod.title ?? 'Stage Check',
1343	          stageName,
1344	          sortOrder: stage.sortOrder ?? idx,
1345	          lessonModuleIds,
1346	        });
1347	      }
1348	    }
1349	
1350	    if (stageCheckEntries.length === 0) {
1351	      return c.json({
1352	        stages: [],
1353	        curriculumId: resolvedCurriculumId,
1354	        curriculumTitle: curriculumRow.title,
1355	      });
1356	    }
1357	
1358	    // ── Step 4: Fetch student's completed lesson events ──────────────────────
1359	    const allLessonIds = [
1360	      ...new Set(stageCheckEntries.flatMap((e) => e.lessonModuleIds)),
1361	    ];
1362	    let completedModuleIdSet = new Set<string>();
1363	    if (allLessonIds.length > 0) {
1364	      const completedEvents = await db
1365	        .select({ trainingModuleId: schema.scheduleEvents.trainingModuleId })
1366	        .from(schema.scheduleEvents)
1367	        .where(
1368	          and(
1369	            eq(schema.scheduleEvents.flightSchoolId, flightSchoolId),
1370	            eq(schema.scheduleEvents.studentId, studentId),
1371	            eq(schema.scheduleEvents.status, 'completed'),
1372	            isNotNull(schema.scheduleEvents.trainingModuleId),
1373	            inArray(schema.scheduleEvents.trainingModuleId, allLessonIds),
1374	          ),
1375	        );
1376	      completedModuleIdSet = new Set(
1377	        completedEvents
1378	          .map((e) => e.trainingModuleId)
1379	          .filter(Boolean) as string[],
1380	      );
1381	    }
1382	
1383	    // ── Step 5: Build stage check entries with eligibility ───────────────────
1384	    // Eligibility: >= 80% of the stage's lesson modules must be completed before
1385	    // the student can schedule the stage check in that stage.
1386	    const ELIGIBILITY_THRESHOLD = 0.8;
