81	function normalizeStandardTask(
82	  value: unknown,
83	  index: number,
84	): CheckrideStandardTask | null {
85	  if (!value || typeof value !== 'object') return null;
86	  const task = value as Partial<CheckrideStandardTask>;
87	  const code = String(task.code ?? '').trim();
88	  const title = String(task.title ?? '').trim();
89	  const area = String(task.area ?? '').trim();
90	  if (!code || !title || !area) return null;
91	  return {
92	    id: String(task.id ?? `${code}-${index}`).trim(),
93	    code,
94	    title,
95	    area,
96	    elements: Array.isArray(task.elements)
97	      ? task.elements.map((item) => String(item ?? '').trim()).filter(Boolean)
98	      : [],
99	    isFaaSourced: task.isFaaSourced === true,
100	    isActive: task.isActive !== false,
101	    sortOrder:
102	      typeof task.sortOrder === 'number' && Number.isFinite(task.sortOrder)
103	        ? Math.trunc(task.sortOrder)
104	        : (index + 1) * 10,
105	  };
106	}
107	
108	function normalizeStandardTasks(value: unknown): CheckrideStandardTask[] {
109	  if (!Array.isArray(value)) return [];
110	  return value
111	    .map((task, index) => normalizeStandardTask(task, index))
112	    .filter((task): task is CheckrideStandardTask => Boolean(task))
113	    .sort(
114	      (a, b) =>
115	        Number(a.sortOrder ?? 0) - Number(b.sortOrder ?? 0) ||
116	        a.code.localeCompare(b.code),
117	    );
118	}
119	
120	function parseTaskElements(value: unknown) {
121	  if (Array.isArray(value)) {
122	    return value.map((item) => String(item ?? '').trim()).filter(Boolean);
123	  }
124	  if (typeof value === 'string') {
125	    return value
126	      .split(/\n|,/)
127	      .map((item) => item.trim())
128	      .filter(Boolean);
129	  }
130	  return [];
131	}
