133	function buildCustomTask(
134	  body: Record<string, unknown>,
135	  existing?: CheckrideStandardTask,
136	): CheckrideStandardTask | { error: string } {
137	  const code = String(body.code ?? existing?.code ?? '').trim();
138	  const title = String(body.title ?? existing?.title ?? '').trim();
139	  const area = String(body.area ?? existing?.area ?? '').trim();
140	  if (!code) return { error: 'Task code is required' };
141	  if (!title) return { error: 'Task title is required' };
142	  if (!area) return { error: 'Area of operation is required' };
143	
144	  return {
145	    id: existing?.id ?? randomUUID(),
146	    code,
147	    title,
148	    area,
149	    elements:
150	      body.elements !== undefined
151	        ? parseTaskElements(body.elements)
152	        : (existing?.elements ?? []),
153	    isFaaSourced: existing?.isFaaSourced === true,
154	    isActive:
155	      typeof body.isActive === 'boolean'
156	        ? body.isActive
157	        : existing?.isActive !== false,
158	    sortOrder:
159	      typeof body.sortOrder === 'number' && Number.isFinite(body.sortOrder)
160	        ? Math.trunc(body.sortOrder)
161	        : (existing?.sortOrder ?? 1000),
162	  };
163	}
