186	async function ensureDefaultStandards(
187	  flightSchoolId: string,
188	  locationId: string,
189	) {
190	  const rows = await db
191	    .select({
192	      id: schema.checkrideStandardCatalogs.id,
193	      standardKey: schema.checkrideStandardCatalogs.standardKey,
194	      tasks: schema.checkrideStandardCatalogs.tasks,
195	    })
196	    .from(schema.checkrideStandardCatalogs)
197	    .where(
198	      and(
199	        eq(schema.checkrideStandardCatalogs.flightSchoolId, flightSchoolId),
200	        eq(schema.checkrideStandardCatalogs.locationId, locationId),
201	      ),
202	    );
203	
204	  const existingKeys = new Set(rows.map((row) => row.standardKey));
205	  const missing = DEFAULT_CHECKRIDE_STANDARDS.filter(
206	    (standard) => !existingKeys.has(standard.standardKey),
207	  );
208	
209	  if (missing.length > 0) {
210	    await db
211	      .insert(schema.checkrideStandardCatalogs)
212	      .values(
213	        missing.map((standard) => ({
214	          flightSchoolId,
215	          locationId,
216	          standardKey: standard.standardKey,
217	          name: standard.name,
218	          sourceKind: standard.sourceKind,
219	          sourceTitle: standard.sourceTitle,
220	          sourceDocument: standard.sourceDocument,
221	          sourceUrl: standard.sourceUrl,
222	          publicationDate: standard.publicationDate,
223	          effectiveDate: standard.effectiveDate,
224	          isFaaSourced: standard.isFaaSourced,
225	          reviewStatus: standard.reviewStatus,
226	          isActive: true,
227	          sortOrder: standard.sortOrder,
228	          tasks: standard.tasks,
229	        })),
230	      )
231	      .onConflictDoNothing();
232	  }
233	
234	  const emptySeededRows = rows.filter((row) => {
235	    const fallback = DEFAULT_CHECKRIDE_STANDARDS.find(
236	      (standard) => standard.standardKey === row.standardKey,
237	    );
238	    return fallback && normalizeStandardTasks(row.tasks).length === 0;
239	  });
240	
241	  for (const row of emptySeededRows) {
242	    const fallback = DEFAULT_CHECKRIDE_STANDARDS.find(
243	      (standard) => standard.standardKey === row.standardKey,
244	    );
245	    if (!fallback) continue;
246	    await db
247	      .update(schema.checkrideStandardCatalogs)
248	      .set({ tasks: fallback.tasks, updatedAt: new Date() })
249	      .where(eq(schema.checkrideStandardCatalogs.id, row.id));
250	  }
251	}
