1	/**
2	 * Checkride Packet PDF Generator
3	 *
4	 * Generates a compiled PDF checkride packet from:
5	 *  - A cover sheet (student name, certificate, school, CFI, date)
6	 *  - Uploaded document pages (IACRA, knowledge test report, logbook, medical, photo ID)
7	 *  - An endorsements summary page
8	 *  - A logbook stats summary (total hours, solo, XC, night, landings)
9	 *
10	 * Returns the PDF as a Uint8Array suitable for:
11	 *  - Returning as base64 for the browser iframe preview
12	 *  - Attaching to an outgoing SendGrid email
13	 *  - Storing to S3 for permanent document record
14	 */
15	
16	import {
17	  PDFDocument,
18	  type PDFPage,
19	  PageSizes,
20	  StandardFonts,
21	  rgb,
22	} from 'pdf-lib';
23	
24	// ─── Colours (matching Hilo brand palette) ────────────────────────────────────
25	const DARK_TEAL = rgb(0.05, 0.47, 0.43); // #0d7872 ≈ teal-700
26	const LIGHT_TEAL = rgb(0.0, 0.54, 0.48); // #008a7a
27	const TEXT_DARK = rgb(0.07, 0.1, 0.1);
28	const TEXT_MUTED = rgb(0.4, 0.45, 0.45);
29	const WHITE = rgb(1, 1, 1);
30	const LIGHT_GREY = rgb(0.96, 0.97, 0.97);
31	const MID_GREY = rgb(0.75, 0.78, 0.78);
32	
33	// ─── Types ────────────────────────────────────────────────────────────────────
34	
35	export interface ItemUpload {
36	  dataUrl: string;
37	  fileName: string;
38	  uploadedBy: string;
39	  uploadedAt: string;
40	}
41	
42	export interface EndorsementRecord {
43	  title: string;
44	  instructorName: string;
45	  signedAt: string | null;
46	  status: string;
47	}
48	
49	export interface LogbookStats {
50	  totalTime: number;
51	  dualReceived: number;
52	  solo: number;
53	  pilotInCommand: number;
54	  crossCountry: number;
55	  instrument: number;
56	  night: number;
57	  dayLandings: number;
58	  nightLandings: number;
59	}
60	
61	export interface PacketSection {
