70	export interface GeneratePacketPdfOptions {
71	  studentName: string;
72	  certificateSought: string; // e.g. "Private Pilot"
73	  schoolName: string;
74	  locationCode: string; // e.g. "KFFZ"
75	  cfiName: string;
76	  cfiCertNumber?: string;
77	  preparedDate: string; // e.g. "April 14, 2026"
78	  sections: PacketSection[];
