85	// ─── Helpers ──────────────────────────────────────────────────────────────────
86	
87	/** Parse a data URL into its MIME type and raw bytes. */
88	function parseDataUrl(
89	  dataUrl: string,
90	): { mimeType: string; bytes: Uint8Array } | null {
91	  const match = /^data:([^;]+);base64,(.+)$/.exec(dataUrl);
92	  if (!match) return null;
93	  const mimeType = match[1];
94	  const base64 = match[2];
95	  const binary = atob(base64);
96	  const bytes = new Uint8Array(binary.length);
97	  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
98	  return { mimeType, bytes };
99	}
100	
101	/** Draw a horizontal rule across the page. */
102	function drawRule(
103	  page: PDFPage,
104	  y: number,
105	  marginX: number,
106	  color = MID_GREY,
107	  thickness = 0.5,
108	) {
109	  const { width } = page.getSize();
110	  page.drawLine({
111	    start: { x: marginX, y },
112	    end: { x: width - marginX, y },
113	    thickness,
114	    color,
115	  });
116	}
