537	// ─── Embed Uploaded Document ──────────────────────────────────────────────────
538	
539	async function embedUploadedDoc(
540	  pdfDoc: PDFDocument,
541	  upload: ItemUpload,
542	  sectionName: string,
543	  itemLabel: string,
544	): Promise<void> {
545	  const parsed = parseDataUrl(upload.dataUrl);
546	  if (!parsed) return;
547	
548	  const { mimeType, bytes } = parsed;
549	
550	  try {
551	    if (mimeType === 'application/pdf') {
552	      // Embed all pages from the uploaded PDF
553	      const uploadedPdf = await PDFDocument.load(bytes);
554	      const pageCount = uploadedPdf.getPageCount();
555	      const copiedPages = await pdfDoc.copyPages(
556	        uploadedPdf,
557	        Array.from({ length: pageCount }, (_, i) => i),
558	      );
559	      for (const p of copiedPages) pdfDoc.addPage(p);
560	    } else if (mimeType === 'image/jpeg' || mimeType === 'image/jpg') {
561	      await addImagePage(
562	        pdfDoc,
563	        bytes,
564	        'jpeg',
565	        sectionName,
566	        itemLabel,
567	        upload.fileName,
568	      );
569	    } else if (mimeType === 'image/png') {
570	      await addImagePage(
571	        pdfDoc,
572	        bytes,
573	        'png',
574	        sectionName,
575	        itemLabel,
576	        upload.fileName,
577	      );
578	    }
579	    // HEIC and other formats are skipped with no error (not supported by pdf-lib)
580	  } catch {
581	    // Best-effort: if a single file fails to embed, skip it rather than failing the whole PDF
582	    await addErrorPage(pdfDoc, itemLabel, upload.fileName);
583	  }
584	}
