586	async function addImagePage(
587	  pdfDoc: PDFDocument,
588	  bytes: Uint8Array,
589	  type: 'jpeg' | 'png',
590	  sectionName: string,
591	  itemLabel: string,
592	  fileName: string,
593	): Promise<void> {
594	  const page = pdfDoc.addPage(PageSizes.Letter);
595	  const { width, height } = page.getSize();
596	  const MARGIN = 40;
597	
598	  const regular = await pdfDoc.embedFont(StandardFonts.Helvetica);
599	  const bold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
600	
601	  // Section label at top
602	  page.drawRectangle({
603	    x: 0,
604	    y: height - 44,
605	    width,
606	    height: 44,
607	    color: DARK_TEAL,
608	  });
609	  page.drawText(sectionName.toUpperCase(), {
610	    x: MARGIN,
611	    y: height - 20,
612	    size: 8,
613	    font: bold,
614	    color: rgb(0.7, 0.9, 0.88),
615	  });
616	  page.drawText(itemLabel, {
617	    x: MARGIN,
618	    y: height - 34,
619	    size: 11,
620	    font: bold,
621	    color: WHITE,
622	  });
623	
624	  // File name
625	  page.drawText(fileName, {
626	    x: MARGIN,
627	    y: height - 56,
628	    size: 8,
629	    font: regular,
630	    color: TEXT_MUTED,
631	  });
632	
633	  // Embed image, centered and scaled to fit
634	  const img =
635	    type === 'jpeg'
636	      ? await pdfDoc.embedJpg(bytes)
637	      : await pdfDoc.embedPng(bytes);
638	
639	  const availW = width - MARGIN * 2;
640	  const availH = height - 80 - MARGIN;
641	  const scale = Math.min(availW / img.width, availH / img.height, 1);
642	  const drawW = img.width * scale;
643	  const drawH = img.height * scale;
644	  const imgX = MARGIN + (availW - drawW) / 2;
645	  const imgY = MARGIN + (availH - drawH) / 2;
646	
647	  page.drawImage(img, { x: imgX, y: imgY, width: drawW, height: drawH });
648	}
