677	
678	/**
679	 * Generates the checkride packet PDF and returns it as a Uint8Array.
680	 *
681	 * Order:
682	 *  1. Cover sheet
683	 *  2. Each uploaded document (in section order)
684	 *  3. Endorsements page
685	 *  4. Logbook stats page (if stats provided)
686	 */
687	export async function generateCheckridePacketPdf(
688	  opts: GeneratePacketPdfOptions,
689	): Promise<Uint8Array> {
690	  const pdfDoc = await PDFDocument.create();
691	
692	  // 1. Cover sheet
693	  await addCoverSheet(pdfDoc, opts);
694	
695	  // 2. Uploaded documents in section/item order
696	  for (const section of opts.sections) {
697	    for (const item of section.items) {
698	      // Find the corresponding upload by matching uploadFileName stored on the item
699	      if (!item.uploadFileName) continue;
700	      const upload = Object.entries(opts.itemUploads).find(
701	        ([, u]) => u.fileName === item.uploadFileName,
702	      )?.[1];
703	      if (!upload) continue;
704	      await embedUploadedDoc(pdfDoc, upload, section.name, item.label);
705	    }
706	  }
707	
708	  // 3. Endorsements
709	  if (opts.endorsements.length > 0) {
710	    await addEndorsementsPage(pdfDoc, opts.endorsements, opts.studentName);
711	  }
712	
713	  // 4. Logbook stats
714	  if (opts.logbookStats) {
715	    await addLogbookStatsPage(pdfDoc, opts.logbookStats, opts.studentName);
716	  }
717	
718	  return pdfDoc.save();
719	}
