358	/**
359	 * Compute the correct student-facing examiner fee from a DPE's profile
360	 * based on certificate type and attempt number.
361	 *
362	 * Decision tree (matches ticket spec):
363	 *   Attempt 1, non-CFI cert → stdCheckrideFeeStudent
364	 *   Attempt 1, CFI cert     → cfiCheckrideFeeStudent
365	 *   Attempt 2+, non-CFI     → stdRecheckFeeStudent
366	 *   Attempt 2+, CFI         → cfiRecheckFeeStudent
367	 */
368	function computeExaminerFeeForRecord(
369	  examiner: schema.DpeExaminer,
370	  certType: string,
371	  attempt: number,
372	): number | undefined {
373	  const isCfi = certType.toUpperCase().includes('CFI');
374	  const isRecheck = attempt >= 2;
375	  const fee = isCfi
376	    ? isRecheck
377	      ? examiner.cfiRecheckFeeStudent
378	      : examiner.cfiCheckrideFeeStudent
379	    : isRecheck
380	      ? examiner.stdRecheckFeeStudent
381	      : examiner.stdCheckrideFeeStudent;
382	  return fee != null && fee > 0 ? fee : undefined;
383	}
