385	/** Build a case-insensitive lookup map from examiner name → DpeExaminer row. */
386	function buildExaminerByNameMap(examiners: schema.DpeExaminer[]) {
387	  const map = new Map<string, schema.DpeExaminer>();
388	  for (const e of examiners) {
389	    const fullName = `${e.firstName ?? ''} ${e.lastName ?? ''}`
390	      .trim()
391	      .toLowerCase();
392	    const nameField = (e.name ?? '').toLowerCase();
393	    if (nameField) map.set(nameField, e);
394	    if (fullName && fullName !== nameField) map.set(fullName, e);
395	  }
396	  return map;
397	}
