1859	/**
1860	 * Compute Levenshtein distance between two lowercase strings.
1861	 * Used for fuzzy student name matching during historical import.
1862	 */
1863	function levenshtein(a: string, b: string): number {
1864	  const m = a.length;
1865	  const n = b.length;
1866	  const dp: number[][] = Array.from({ length: m + 1 }, (_, i) =>
1867	    Array.from({ length: n + 1 }, (_, j) => (i === 0 ? j : j === 0 ? i : 0)),
1868	  );
1869	  for (let i = 1; i <= m; i++) {
1870	    for (let j = 1; j <= n; j++) {
1871	      dp[i][j] =
1872	        a[i - 1] === b[j - 1]
1873	          ? dp[i - 1][j - 1]
1874	          : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
1875	    }
1876	  }
1877	  return dp[m][n];
1878	}
1879	
1880	/** Fuzzy-match a name against a list of candidates; returns best match if score is acceptable. */
1881	function fuzzyMatchName(
1882	  query: string,
1883	  candidates: { id: string; name: string }[],
1884	): { id: string; name: string; score: number } | null {
1885	  if (!query) return null;
1886	  const q = query.toLowerCase().trim();
1887	  let best: { id: string; name: string; score: number } | null = null;
1888	  for (const c of candidates) {
1889	    const n = c.name.toLowerCase().trim();
1890	    if (n === q) return { ...c, score: 100 };
1891	    const dist = levenshtein(q, n);
1892	    const maxLen = Math.max(q.length, n.length);
1893	    const score = Math.round((1 - dist / maxLen) * 100);
1894	    if (!best || score > best.score) best = { ...c, score };
1895	  }
1896	  // Only return match if similarity >= 70%
1897	  return best && best.score >= 70 ? best : null;
1898	}
