5684	/**
5685	 * Fire checkride.passed or checkride.failed trigger after a result is recorded.
5686	 * Called fire-and-forget from history POST and PUT handlers.
5687	 */
5688	async function fireCheckrideOutcomeTrigger(
5689	  locationId: string,
5690	  flightSchoolId: string,
5691	  record: {
5692	    id: string;
5693	    studentId?: string | null;
5694	    type: string;
5695	    dpeName?: string | null;
5696	    date: Date | string;
5697	    notes?: string | null;
5698	  },
5699	  result: string,
5700	  extra: Record<string, unknown>,
5701	): Promise<void> {
5702	  const normalizedResult = result.toLowerCase();
5703	  const isPassed = normalizedResult === 'passed' || normalizedResult === 'pass';
5704	  const isFailed =
5705	    normalizedResult === 'failed' ||
5706	    normalizedResult === 'fail' ||
5707	    normalizedResult === 'disapproved' ||
5708	    normalizedResult === 'discontinued';
5709	  if (!isPassed && !isFailed) return;
5710	
5711	  const trigger = isPassed ? 'checkride.passed' : 'checkride.failed';
5712	
5713	  // Look up student info
5714	  let studentName: string | null = null;
5715	  let studentPhone: string | null = null;
5716	  let studentEmail: string | null = null;
5717	  if (record.studentId) {
5718	    const [student] = await db
5719	      .select({
5720	        name: schema.users.name,
5721	        phone: schema.users.phone,
5722	        email: schema.users.email,
5723	      })
5724	      .from(schema.users)
5725	      .where(eq(schema.users.id, record.studentId))
5726	      .limit(1);
5727	    if (student) {
5728	      studentName = student.name;
5729	      studentPhone = student.phone ?? null;
5730	      studentEmail = student.email ?? null;
5731	    }
5732	  }
5733	
5734	  // Look up location name
5735	  const [loc] = await db
5736	    .select({ name: schema.locations.name })
5737	    .from(schema.locations)
5738	    .where(eq(schema.locations.id, locationId))
5739	    .limit(1);
5740	
5741	  const certType =
5742	    (extra.certificateType as string) || record.type || 'Checkride';
5743	  const examinerName = (extra.examinerName as string) || record.dpeName || null;
5744	  const attempt = typeof extra.attempt === 'number' ? extra.attempt : 1;
5745	  const areasOfDisapproval = Array.isArray(extra.areasOfDisapproval)
5746	    ? (extra.areasOfDisapproval as string[]).join(', ')
5747	    : null;
5748	
5749	  const dateStr = toDateStr(record.date);
5750	  const today = new Date().toISOString().substring(0, 10);
5751	  const dedup = `${trigger}-${record.id}-${today}`;
5752	
5753	  const { triggerWorkflowsForEvent } = await import(
5754	    '@/lib/automations/triggerWorkflow'
5755	  );
5756	  await triggerWorkflowsForEvent(
5757	    trigger,
5758	    {
5759	      eventId: dedup,
5760	      flightSchoolId,
5761	      locationId,
5762	      studentId: record.studentId ?? null,
5763	      studentName,
5764	      studentPhone,
5765	      studentEmail,
5766	      locationName: loc?.name ?? null,
5767	      certificateType: certType,
5768	      attemptNumber: attempt,
5769	      examinerName,
5770	      checkrideDate: dateStr,
5771	      areasOfDisapproval,
5772	    },
5773	    flightSchoolId,
5774	    locationId,
5775	  );
5776	}
